import { atom, read, update } from 'claude-code'
import type { EngineInterface, RenderChildren, PluginOptions, Register } from 'claude-code'

import type { NeedsYouWait } from '../types'
import {
  ackLine,
  blockedBody,
  blockedDetail,
  channels,
  errorBody,
  finishedBody,
  formatLeft,
  isUnder,
  parseDuration,
  parseFront,
  pingLine,
  plain,
  summarize,
  sweep,
  title,
  turnVerdict,
} from './logic'
import type { BodyMode, Kind, Mode, Outcome } from './logic'

// Per-session state lives in $.state so a hot reload keeps waits, the turn flag and the ack.
const userTurn = atom({ plugin: 'needs-you', key: 'userTurn' } as const, false)
const dialogMs = atom({ plugin: 'needs-you', key: 'dialogMs' } as const, 0)
const waits = atom({ plugin: 'needs-you', key: 'waits' } as const, [])
const lastInteractionAt = atom({ plugin: 'needs-you', key: 'lastInteractionAt' } as const, null)
const lastPingAt = atom({ plugin: 'needs-you', key: 'lastPingAt' } as const, null)
const bandAtom = atom({ plugin: 'needs-you', key: 'band' } as const, null)
const labelAtom = atom({ plugin: 'needs-you', key: 'label' } as const, '')
const branchAtom = atom({ plugin: 'needs-you', key: 'branch' } as const, null)
const ackPending = atom({ plugin: 'needs-you', key: 'ackPending' } as const, null)

// Global quiet mode, shared by every session through $.store: one key per concern.
const MODE_KEY = 'needs-you:mode'
const UNTIL_KEY = 'needs-you:until'

const LOG = '/.claude/state/needs-you.log'
/** macOS's own Glass sound, played in place (not bundled: it's Apple's file). */
const SOUND = '/System/Library/Sounds/Glass.aiff'
const PERM_ID = 'perm'
const USER_ORIGINS = new Set(['composer', 'bridge', 'sdk'])

/** One-line switch: true draws the band at rest too (`CC Alerts: on [ Quiet 2h ] [ Off 8h ]`). */
const BAND_ALWAYS = false

type Config = {
  minTurnMs: number
  waitMs: number
  repeatMs: number
  repeatMin: number
  gapMs: number
  lookingMs: number
  hostApp: string
  bodyMode: BodyMode
  kindOnlyPaths: string
}

function readConfig(options: PluginOptions): Config {
  const num = (k: string, d: number) => {
    const v = options[k]
    return typeof v === 'number' && v >= 0 ? v : d
  }
  const str = (k: string, d: string) => {
    const v = options[k]
    return typeof v === 'string' ? v : d
  }
  const repeatMin = num('repeatMinutes', 5)
  return {
    minTurnMs: num('minTurnSeconds', 60) * 1000,
    waitMs: num('waitSeconds', 15) * 1000,
    repeatMs: repeatMin * 60_000,
    repeatMin,
    gapMs: num('sessionGapSeconds', 60) * 1000,
    lookingMs: num('lookingWindowSeconds', 30) * 1000,
    hostApp: str('hostApp', ''),
    bodyMode: options.bodyMode === 'kind-only' ? 'kind-only' : 'full',
    kindOnlyPaths: str('kindOnlyPaths', ''),
  }
}

// ---------- plumbing ----------

/** Fire-and-forget with the failure routed to the debug log. */
function safe($: EngineInterface, p: Promise<unknown>): void {
  p.catch(err => $.ui.log(`needs-you: ${String(err)}`, { to: 'debug' }))
}

async function home($: EngineInterface): Promise<string> {
  return (await $.env.get('HOME')) ?? ''
}

/** O_APPEND via the shell, as outward-gate does: concurrent sessions can't clobber each other's lines. */
async function appendLog($: EngineInterface, line: string): Promise<void> {
  try {
    await $.process.run(['/bin/sh', '-c', 'mkdir -p "$(dirname "$1")" && printf "%s\\n" "$2" >> "$1"', 'sh', `${await home($)}${LOG}`, line])
  } catch (err) {
    $.ui.log(`needs-you: log write failed: ${String(err)}`, { to: 'debug' })
  }
}

async function projectName($: EngineInterface): Promise<string> {
  const root = await $.session.root()
  return root.split('/').filter(p => p !== '').pop() ?? root
}

async function bodyModeOf($: EngineInterface, cfg: Config): Promise<BodyMode> {
  if (cfg.bodyMode === 'kind-only') return 'kind-only'
  return isUnder(await $.session.root(), cfg.kindOnlyPaths, await home($)) ? 'kind-only' : 'full'
}

/** Cached per session: the engine's repo info has no branch. */
async function branchOf($: EngineInterface): Promise<string> {
  const cached = await read($, branchAtom)
  if (cached !== null) return cached
  let branch = 'no-git'
  try {
    const r = await $.process.run(['git', 'rev-parse', '--abbrev-ref', 'HEAD'], { timeoutMs: 3000 })
    if (r.exitCode === 0 && r.stdout.trim() !== '') branch = r.stdout.trim()
  } catch {
    // Not a repo, or git missing: the title just says no-git.
  }
  await update($, branchAtom, () => branch)
  return branch
}

async function sessionTitle($: EngineInterface): Promise<string> {
  return title({ project: await projectName($), branch: await branchOf($), id: await $.session.id(), label: await read($, labelAtom) })
}

// ---------- quiet mode ----------

type Current = { mode: Mode; until: number | null; source: string }

/** Reads the global mode once, auto-clearing an expired one. */
async function currentMode($: EngineInterface, now: number): Promise<Current> {
  const stored = await $.store.get(MODE_KEY)
  const until = await $.store.get(UNTIL_KEY)
  let mode: Mode = stored === 'quiet' || stored === 'off' ? stored : 'on'
  let end = typeof until === 'number' ? until : null
  if (mode !== 'on' && end !== null && end <= now) {
    await $.store.delete(MODE_KEY)
    await $.store.delete(UNTIL_KEY)
    mode = 'on'
    end = null
  }
  const env = (await $.env.get('NEEDS_YOU'))?.trim().toLowerCase()
  if (env === 'off') return { mode: 'off', until: null, source: 'NEEDS_YOU=off' }
  return { mode, until: mode === 'on' ? null : end, source: mode === 'on' ? '' : '/ping' }
}

/** $.store doesn't re-render: each session mirrors it into $.state on its own sweep (≤ 15 s cross-tab lag). */
async function mirrorBand($: EngineInterface): Promise<void> {
  const now = await $.clock.now()
  const c = await currentMode($, now)
  const left = c.until === null ? 'until turned on' : `${formatLeft(c.until - now)} left`
  const prev = await read($, bandAtom)
  if (prev === null || prev.mode !== c.mode || prev.until !== c.until || prev.left !== left) {
    await update($, bandAtom, () => ({ mode: c.mode, until: c.until, left }))
  }
}

async function setMode($: EngineInterface, mode: Mode, ms: number | null): Promise<void> {
  if (mode === 'on') {
    await $.store.delete(MODE_KEY)
    await $.store.delete(UNTIL_KEY)
  } else {
    await $.store.set(MODE_KEY, mode)
    if (ms === null) await $.store.delete(UNTIL_KEY)
    else await $.store.set(UNTIL_KEY, (await $.clock.now()) + ms)
  }
  await mirrorBand($)
  await noteInteraction($)
}

// ---------- interaction + ack ----------

/** Any sign the user is at this session: keystroke, prompt, band press, an answered dialog. */
async function noteInteraction($: EngineInterface): Promise<void> {
  const now = await $.clock.now()
  const last = await read($, lastInteractionAt)
  if (last === null || now - last >= 1000) await update($, lastInteractionAt, () => now)
  const ack = await read($, ackPending)
  if (ack !== null) {
    await update($, ackPending, () => null)
    await appendLog($, ackLine({ at: now, id: ack.id, session: await $.session.id(), delayMs: now - ack.at }))
  }
}

// ---------- the ping ----------

async function hostIsFront($: EngineInterface, cfg: Config): Promise<boolean> {
  const host = cfg.hostApp !== '' ? cfg.hostApp : ((await $.env.get('__CFBundleIdentifier')) ?? '')
  if (host === '') return false
  try {
    const r = await $.process.run(['/bin/sh', '-c', 'lsappinfo info -only bundleid "$(lsappinfo front)"'], { timeoutMs: 3000 })
    return r.exitCode === 0 && parseFront(r.stdout) === host
  } catch {
    return false // unknown frontmost counts as not looking: ping
  }
}

type PingRequest = { kind: Kind; body: string; seconds: number; force?: boolean }

async function logOnly($: EngineInterface, kind: Kind, outcome: Outcome, seconds: number): Promise<void> {
  const at = await $.clock.now()
  const session = await $.session.id()
  await appendLog($, pingLine({ at, id: `${at.toString(36)}-${kind}`, session, project: await projectName($), kind, outcome, seconds }))
}

async function ping($: EngineInterface, cfg: Config, isInteractive: boolean, req: PingRequest): Promise<void> {
  if (!isInteractive) return // headless: never ping, never spawn a process
  const now = await $.clock.now()
  const session = await $.session.id()
  const mode = await currentMode($, now)
  const nonTerminal = (await $.session.surfaces()).some(s => s !== 'terminal')
  const hostFront = mode.mode === 'off' || nonTerminal ? false : await hostIsFront($, cfg)
  const last = await read($, lastInteractionAt)
  const ch = channels({
    kind: req.kind,
    mode: mode.mode,
    hostFront,
    interactedRecently: req.force !== true && last !== null && now - last < cfg.lookingMs,
    nonTerminal,
  })
  const heading = await sessionTitle($)
  const id = `${now.toString(36)}-${req.kind}`

  if (ch.banner) {
    await banner($, heading, req.body)
    await update($, ackPending, () => ({ id, at: now }))
  }
  if (ch.sound) await $.process.run(['afplay', SOUND], { timeoutMs: 5000 }).catch(err => $.ui.log(`needs-you: sound failed: ${String(err)}`, { to: 'debug' }))
  if (ch.toast) $.ui.toast(`CC Alerts · ${heading} — ${req.body}`, { timeoutMs: 8000 })
  await appendLog($, pingLine({ at: now, id, session, project: await projectName($), kind: req.kind, outcome: ch.outcome, seconds: req.seconds }))
  if ((req.kind === 'finished' || req.kind === 'error') && req.force !== true) await update($, lastPingAt, () => now)
}

// ---------- banner ----------

/** A copy of terminal-notifier with the Claude icon (see README): macOS takes a banner's icon from the sending app. */
const NOTIFIER = 'Applications/CC Alerts.app/Contents/MacOS/terminal-notifier'

/** Text always goes in as argv items, never interpolated into a script. Falls back to osascript (Script Editor's icon). */
async function banner($: EngineInterface, title: string, body: string): Promise<void> {
  const sent = await $.process
    .run([`${await home($)}/${NOTIFIER}`, '-title', plain(title), '-message', plain(body)], { timeoutMs: 5000 })
    .catch(() => undefined)
  if (sent?.exitCode === 0) return
  await $.process
    .run(['osascript', '-e', 'on run argv', '-e', 'display notification (item 1 of argv) with title (item 2 of argv)', '-e', 'end run', '--', body, title], { timeoutMs: 5000 })
    .catch(err => $.ui.log(`needs-you: banner failed: ${String(err)}`, { to: 'debug' }))
}

// ---------- blocked waits ----------

async function startWait($: EngineInterface, w: Pick<NeedsYouWait, 'id' | 'kind' | 'tool' | 'detail'>): Promise<void> {
  const now = await $.clock.now()
  await update($, waits, ws => (ws.some(x => x.id === w.id) ? ws : [...ws, { ...w, startedAt: now, pinged: false, repeated: false }]))
}

/** Removes matching waits; their time is subtracted from the turn. `answered` = the user resolved it (not Esc, /clear, abort). */
async function endWaits($: EngineInterface, match: (w: NeedsYouWait) => boolean, answered: boolean): Promise<void> {
  if (!(await read($, waits)).some(match)) return
  let gone: NeedsYouWait[] = []
  await update($, waits, ws => {
    gone = ws.filter(match)
    return ws.filter(w => !match(w))
  })
  const now = await $.clock.now()
  const spent = gone.reduce((sum, w) => sum + Math.max(0, now - w.startedAt), 0)
  if (spent > 0) await update($, dialogMs, ms => ms + spent)
  if (answered && gone.length > 0) await noteInteraction($)
}

/** The sweep: idempotent via per-wait flags, so reload, a 2nd timer or a racing event can't double-ping. */
async function tick($: EngineInterface, cfg: Config, isInteractive: boolean): Promise<void> {
  if (!isInteractive) return
  const list = await read($, waits)
  if (list.length === 0) return
  const now = await $.clock.now()
  const act = sweep(list, now, { waitMs: cfg.waitMs, repeatMs: cfg.repeatMs })
  const id = act.ping ?? act.repeat
  if (id === undefined) return
  const repeat = act.repeat !== undefined
  let claimed: NeedsYouWait | undefined
  await update($, waits, ws => {
    claimed = ws.find(w => w.id === id && (repeat ? !w.repeated : !w.pinged))
    return claimed === undefined ? ws : ws.map(w => (w.id === id ? (repeat ? { ...w, repeated: true } : { ...w, pinged: true, repeated: now - w.startedAt >= cfg.repeatMs }) : w))
  })
  if (claimed === undefined) return
  await ping($, cfg, isInteractive, {
    kind: repeat ? 'repeat' : 'blocked',
    body: blockedBody(claimed.detail, repeat, cfg.repeatMs / 60_000),
    seconds: (now - claimed.startedAt) / 1000,
  })
}

async function watched<R>($: EngineInterface, w: Pick<NeedsYouWait, 'id' | 'kind' | 'tool' | 'detail'>, signal: AbortSignal, run: () => Promise<R>): Promise<R> {
  await startWait($, w)
  try {
    return await run()
  } finally {
    await endWaits($, x => x.id === w.id, !signal.aborted)
  }
}

// ---------- /ping ----------

const USAGE = 'Usage: /ping [on | quiet [30m|2h] | off [30m|2h] | test | log | name <label>]'

async function statusText($: EngineInterface, cfg: Config): Promise<string> {
  const now = await $.clock.now()
  const c = await currentMode($, now)
  const state = c.mode === 'on' ? 'ON' : `${c.mode.toUpperCase()}${c.until === null ? '' : ` (${formatLeft(c.until - now)} left)`}${c.source === '/ping' ? '' : ` [${c.source}]`}`
  const detected = (await $.env.get('__CFBundleIdentifier')) ?? 'unknown'
  const host = cfg.hostApp !== '' ? `${cfg.hostApp} (config override; detected ${detected})` : detected
  return [
    `CC Alerts: ${state}.`,
    `Host app: ${host}.`,
    `This session: ${await sessionTitle($)}.`,
    `Pings: finished turns ≥ ${cfg.minTurnMs / 1000}s, blocked waits ≥ ${cfg.waitMs / 1000}s (one repeat at ${cfg.repeatMin}m). Quiet: banner+toast, no sound. Off: toast + log only.`,
  ].join(' ')
}

async function logText($: EngineInterface): Promise<string> {
  const path = `${await home($)}${LOG}`
  let text = ''
  try {
    text = await $.fs.read(path)
  } catch {
    return `No log yet at ${path}.`
  }
  const lines = text.split('\n').filter(l => l !== '')
  return `${lines.slice(-20).join('\n')}\n${summarize(lines, await $.clock.now())}`
}

export const register: Register = (on, options) => {
  const cfg = readConfig(options)
  // A fact about this process: session.start re-sets it on every (re)load.
  let isInteractive = false

  on('session.start', async ($, e, next) => {
    isInteractive = e.isInteractive
    await $.command.register({
      name: 'ping',
      description: 'CC Alerts: status, on, quiet [2h], off [8h], test, log, name <label>',
      argumentHint: '[on | quiet [dur] | off [dur] | test | log | name <label>]',
    })
    // Timers die on reload; the waits themselves are in $.state, so the new sweep picks them up.
    $.clock.every(5000, () => safe($, tick($, cfg, isInteractive)))
    $.clock.every(15_000, () => safe($, mirrorBand($)))
    await mirrorBand($)
    safe($, tick($, cfg, isInteractive))
    return next(e)
  })

  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') {
      await update($, waits, () => [])
      await update($, dialogMs, () => 0)
      await update($, userTurn, () => false)
      await update($, ackPending, () => null)
    }
    return next(e)
  })

  on('command.run', { command: 'ping' }, async ($, e) => {
    const [verb = '', ...rest] = e.args.trim().split(/\s+/)
    const arg = rest.join(' ')
    if (verb === '') return { text: await statusText($, cfg) }
    if (verb === 'on') {
      await setMode($, 'on', null)
      return { text: 'CC Alerts: ON.' }
    }
    if (verb === 'quiet' || verb === 'off') {
      const ms = arg === '' ? null : parseDuration(arg)
      if (ms === undefined) return { text: `Can't read "${arg}". Use e.g. /ping ${verb} 2h or /ping ${verb} 30m.` }
      await setMode($, verb, ms)
      const what = verb === 'quiet' ? 'no sound (banner + toast)' : 'no banner, no sound (toast + log only)'
      return { text: `CC Alerts: ${verb.toUpperCase()} — ${what}${ms === null ? ' until /ping on' : ` for ${formatLeft(ms)}`}.` }
    }
    if (verb === 'test') {
      await noteInteraction($)
      await ping($, cfg, isInteractive, { kind: 'finished', body: 'Done · test · this is a sample ping', seconds: 0, force: true })
      return { text: 'Sample ping sent through the real path (check the log with /ping log).' }
    }
    if (verb === 'log') return { text: await logText($) }
    if (verb === 'name') {
      await update($, labelAtom, () => arg)
      return { text: arg === '' ? 'Session label cleared.' : `Session tag is now: ${await sessionTitle($)}` }
    }
    return { text: USAGE }
  })

  // ---- interaction clock ----
  on('prompt.edit', async ($, e, next) => {
    await noteInteraction($)
    safe($, tick($, cfg, isInteractive)) // evaluate on the next event too, in case a timer was lost to a reload
    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    const kind = e.origin.kind
    const user = USER_ORIGINS.has(kind)
    // The user's turn: their own prompt, or the wake-up a background task they launched caused. Never peer/plugin turns.
    if (user || (kind === 'task-notification' && e.turnId === undefined)) await update($, userTurn, () => true)
    else if (e.turnId === undefined) await update($, userTurn, () => false)
    if (user) await noteInteraction($)
    return next(e)
  })

  // ---- trigger 1: turn finished ----
  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId !== undefined) return result // subagent turns never ping
    await endWaits($, () => true, false)
    const started = await read($, userTurn)
    await update($, userTurn, () => false)
    const spent = await read($, dialogMs)
    await update($, dialogMs, () => 0)
    const now = await $.clock.now()
    const lastPing = await read($, lastPingAt)
    const effectiveMs = Math.max(0, e.durationMs - spent)
    const verdict = turnVerdict({
      reason: e.reason,
      answer: e.answer,
      effectiveMs,
      minMs: cfg.minTurnMs,
      startedByUser: started,
      sinceLastPingMs: lastPing === null ? null : now - lastPing,
      gapMs: cfg.gapMs,
    })
    if (verdict === 'none') return result
    const kind: Kind = e.reason === 'error' || e.reason === 'refusal' ? 'error' : 'finished'
    // Fire-and-forget: lsappinfo/osascript must not eat the hook's own budget.
    $.clock.after(0, () => {
      if (verdict === 'gap') return safe($, isInteractive ? logOnly($, kind, 'gap', effectiveMs / 1000) : Promise.resolve())
      safe(
        $,
        bodyModeOf($, cfg).then(bodyMode =>
          ping($, cfg, isInteractive, {
            kind,
            body: e.reason === 'error' || e.reason === 'refusal' ? errorBody(e.reason) : finishedBody({ answer: e.answer, durationMs: effectiveMs, bodyMode }),
            seconds: effectiveMs / 1000,
          }),
        ),
      )
    })
    return result
  })

  // ---- trigger 2: blocked waits ----
  // Permission dialog: classic.PermissionRequest has no tool_use_id, so the wait is keyed by session.
  on('classic.PermissionRequest', async ($, e, next) => {
    const detail = blockedDetail({ kind: 'permission', tool: e.tool_name, bodyMode: await bodyModeOf($, cfg) })
    await startWait($, { id: PERM_ID, kind: 'permission', tool: e.tool_name, detail })
    safe($, tick($, cfg, isInteractive))
    return next(e)
  })
  on('classic.PostToolUse', async ($, e, next) => {
    await endWaits($, w => w.kind === 'permission' && w.tool === e.tool_name, true)
    return next(e)
  })
  on('classic.PostToolUseFailure', async ($, e, next) => {
    await endWaits($, w => w.kind === 'permission' && w.tool === e.tool_name, true)
    return next(e)
  })

  // Plan approval and questions (this also covers outward-gate, whose dialog is an AskUserQuestion).
  on('tool.call', { tool: 'ExitPlanMode' }, async ($, e, next) => {
    safe($, tick($, cfg, isInteractive))
    return watched($, { id: e.tool_use_id, kind: 'plan', tool: '', detail: blockedDetail({ kind: 'plan', bodyMode: 'full' }) }, next.signal, () => next(e))
  })
  on('tool.call', { tool: 'AskUserQuestion' }, async ($, e, next) => {
    safe($, tick($, cfg, isInteractive))
    const detail = blockedDetail({ kind: 'question', header: e.questions[0]?.header, bodyMode: await bodyModeOf($, cfg) })
    return watched($, { id: e.tool_use_id, kind: 'question', tool: '', detail }, next.signal, () => next(e))
  })

  // A new model request means every dialog of the previous step is over: backstop if a reload orphaned a wait.
  on('turn.step', async function* ($, e, next) {
    if (e.agentId === undefined) await endWaits($, () => true, false)
    return yield* next(e)
  })
  // Esc / abort cancels pending waits and their repeat.
  on('turn.abort', async ($, e, next) => {
    await endWaits($, () => true, false)
    return next(e)
  })

  // ---- the band ----
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || e.props.view.agentId !== undefined) return next(e)
    const band = await read($, bandAtom)
    const mode = band?.mode ?? 'on'
    if (mode === 'on' && !BAND_ALWAYS) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    // The band is one site shared by every mod: stack our row on what the mods beneath draw, never replace it.
    const withBelow = async (mine: RenderChildren) => <Box flexDirection="column">{mine}{await next(e)}</Box>
    if (mode === 'on') {
      return withBelow(
        <Box flexDirection="row" gap={1}>
          <Text dimColor>CC Alerts: on</Text>
          <Button key="ping-quiet" label="Quiet 2h" onPress={() => safe($, setMode($, 'quiet', 2 * 3_600_000))} />
          <Button key="ping-off" label="Off 8h" onPress={() => safe($, setMode($, 'off', 8 * 3_600_000))} />
        </Box>
      )
    }
    return withBelow(
      <Box flexDirection="row" gap={1}>
        <Text color="yellow">{`CC Alerts: ${mode === 'off' ? 'OFF' : 'quiet'} · ${band?.left ?? ''}`}</Text>
        <Button key="ping-on" label="Back on" onPress={() => safe($, setMode($, 'on', null))} />
      </Box>
    )
  })
}

