import type { NeedsYouWait } from '../types'

export type Kind = 'finished' | 'error' | 'blocked' | 'repeat'
export type Mode = 'on' | 'quiet' | 'off'
export type Outcome = 'banner' | 'toast:looking' | 'off' | 'quiet' | 'headless' | 'gap'
export type BodyMode = 'full' | 'kind-only'

export const TITLE_MAX = 40
export const BODY_MAX = 80
export const ACK_WINDOW_MS = 180_000

// ---------- durations ----------

/** "8h" / "30m" / "2d" / "45" (minutes) → ms; undefined when unreadable. */
export function parseDuration(text: string): number | undefined {
  const m = /^(\d+(?:\.\d+)?)\s*([mhd]?)$/i.exec(text.trim())
  if (!m) return undefined
  const n = Number(m[1])
  const unit = (m[2] ?? '').toLowerCase()
  const ms = n * (unit === 'h' ? 3_600_000 : unit === 'd' ? 86_400_000 : 60_000)
  return ms > 0 ? ms : undefined
}

export function formatLeft(ms: number): string {
  const min = Math.max(1, Math.ceil(ms / 60_000))
  if (min < 60) return `${min}m`
  const h = Math.floor(min / 60)
  return min % 60 ? `${h}h${min % 60}m` : `${h}h`
}

/** A turn's length as "45s", "12m", "1h5m". */
export function formatDuration(ms: number): string {
  const s = Math.floor(ms / 1000)
  if (s < 60) return `${s}s`
  const min = Math.floor(s / 60)
  if (min < 60) return `${min}m`
  const h = Math.floor(min / 60)
  return min % 60 ? `${h}h${min % 60}m` : `${h}h`
}

// ---------- text safety: strip → redact → truncate ----------

const SEGMENTER = new Intl.Segmenter(undefined, { granularity: 'grapheme' })

export function graphemes(text: string): string[] {
  return Array.from(SEGMENTER.segment(text), s => s.segment)
}

/** Truncates by grapheme (never splits an emoji or combining mark), ending in "…" when cut. */
export function truncate(text: string, max: number): string {
  const g = graphemes(text)
  return g.length <= max ? text : `${g.slice(0, Math.max(0, max - 1)).join('')}…`
}

const KEY_SHAPES: readonly RegExp[] = [
  /\bsk-[A-Za-z0-9_-]{8,}/g,
  /\bgh[pousr]_[A-Za-z0-9]{10,}/g,
  /\bxox[abprs]-[A-Za-z0-9-]{8,}/g,
  /\bAKIA[0-9A-Z]{12,}/g,
  /\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_.-]+/g,
  /[A-Za-z0-9+/_=-]{32,}/g,
]

export function redact(text: string): string {
  return KEY_SHAPES.reduce((t, re) => t.replace(re, '[redacted]'), text)
}

/** Markdown and control characters out; one line. */
export function stripMarkup(text: string): string {
  return text
    .replace(/[\p{Cc}\p{Cf}]/gu, ' ')
    .replace(/^\s*(?:[-*+>]\s+|\d+\.\s+)/, '')
    .replace(/^\s*#+\s*/, '')
    .replace(/\*\*|`+/g, '')
    .replace(/\s+/g, ' ')
    .trim()
}

/** Strip, then redact, then truncate: redaction must see the whole secret before a cut can hide half of it. */
export function safeText(text: string, max: number): string {
  return truncate(redact(stripMarkup(text)), max)
}

/** The last sentence of the reply's last line; '' for a code fence, table row or empty reply. */
export function lastSentence(answer: string): string {
  const lines = answer.split('\n').map(l => l.trim()).filter(l => l !== '')
  const line = lines[lines.length - 1] ?? ''
  if (line.startsWith('|') || line.startsWith('```')) return ''
  const sentences = line.split(/(?<=[.!?])\s+/)
  return stripMarkup(sentences[sentences.length - 1] ?? '')
}

export function endsWithQuestion(answer: string): boolean {
  const lines = answer.split('\n').map(l => l.trim()).filter(l => l !== '')
  return (lines[lines.length - 1] ?? '').endsWith('?')
}

/** `Done · 12m · sentence` / `Needs answer · …` / kind-only; always ≤ BODY_MAX. */
export function finishedBody(args: { answer: string; durationMs: number; bodyMode: BodyMode }): string {
  const head = `${endsWithQuestion(args.answer) ? 'Needs answer' : 'Done'} · ${formatDuration(args.durationMs)}`
  if (args.bodyMode === 'kind-only') return head
  const sentence = redact(lastSentence(args.answer))
  if (sentence.length < 10) return head
  const room = BODY_MAX - graphemes(head).length - 3
  return room < 10 ? head : `${head} · ${truncate(sentence, room)}`
}

export function errorBody(reason: 'error' | 'refusal'): string {
  return reason === 'refusal' ? 'Error · refusal' : 'Error · API error'
}

/** Dialog type + header, never question text. */
export function blockedDetail(args: { kind: NeedsYouWait['kind']; tool?: string; header?: string; bodyMode: BodyMode }): string {
  if (args.kind === 'plan') return 'Plan approval'
  if (args.kind === 'permission') {
    return args.bodyMode === 'kind-only' || !args.tool ? 'Permission' : `${safeText(args.tool, 30)} permission`
  }
  return args.bodyMode === 'kind-only' || !args.header ? 'Question' : `Question · ${safeText(args.header, 30)}`
}

export function blockedBody(detail: string, repeat: boolean, repeatMin: number): string {
  return truncate(repeat ? `Still waiting · ${repeatMin}m · ${detail}` : `Waiting · ${detail}`, BODY_MAX)
}

// ---------- title ----------

/** FNV-1a over the session id, 4 base-36 chars: stable across hot reload. */
export function hash4(id: string): string {
  let h = 0x811c9dc5
  for (const ch of id) h = Math.imul(h ^ ch.charCodeAt(0), 0x01000193) >>> 0
  return h.toString(36).padStart(4, '0').slice(-4)
}

/** `<project> · <branch> · #hash[ · label]`, ≤ TITLE_MAX: the longest free-text part is cut until it fits. */
export function title(args: { project: string; branch: string; id: string; label: string }): string {
  const tag = `#${hash4(args.id)}`
  const parts = { project: stripMarkup(args.project), branch: stripMarkup(args.branch), label: stripMarkup(args.label) }
  const join = () => [parts.project, parts.branch, tag, parts.label].filter(p => p !== '').join(' · ')
  while (graphemes(join()).length > TITLE_MAX) {
    const longest = (['project', 'branch', 'label'] as const).reduce((a, b) => (graphemes(parts[b]).length > graphemes(parts[a]).length ? b : a))
    const len = graphemes(parts[longest]).length
    if (len <= 1) return truncate(join(), TITLE_MAX)
    parts[longest] = truncate(parts[longest], len - 1)
  }
  return join()
}

// ---------- tiers ----------

export type Channels = { banner: boolean; sound: boolean; toast: boolean; outcome: Outcome }

/**
 * Three tiers, then the quiet mode on top.
 * Host not in front → banner+sound+toast. In front → banner+toast. In front and just interacted →
 * toast only (finished/error only: a blocked wait always gets its banner).
 */
export function channels(args: {
  kind: Kind
  mode: Mode
  hostFront: boolean
  interactedRecently: boolean
  nonTerminal: boolean
}): Channels {
  if (args.mode === 'off') return { banner: false, sound: false, toast: true, outcome: 'off' }
  const looking = args.hostFront && !args.nonTerminal
  const toastOnly = looking && args.interactedRecently && (args.kind === 'finished' || args.kind === 'error')
  if (toastOnly) return { banner: false, sound: false, toast: true, outcome: 'toast:looking' }
  const sound = !looking
  if (args.mode === 'quiet') return { banner: true, sound: false, toast: true, outcome: sound ? 'quiet' : 'banner' }
  return { banner: true, sound, toast: true, outcome: 'banner' }
}

// ---------- turn rule ----------

export type TurnVerdict = 'none' | 'finished' | 'error' | 'gap'

export function turnVerdict(args: {
  reason: 'answer' | 'aborted' | 'refusal' | 'error'
  answer: string
  effectiveMs: number
  minMs: number
  startedByUser: boolean
  sinceLastPingMs: number | null
  gapMs: number
}): TurnVerdict {
  if (!args.startedByUser || args.reason === 'aborted') return 'none'
  const kind: TurnVerdict | undefined =
    args.reason === 'error' || args.reason === 'refusal'
      ? 'error'
      : args.answer.trim() !== '' && args.effectiveMs >= args.minMs
        ? 'finished'
        : undefined
  if (kind === undefined) return 'none'
  return args.sinceLastPingMs !== null && args.sinceLastPingMs < args.gapMs ? 'gap' : kind
}

// ---------- blocked-wait sweep ----------

/**
 * What the sweep should do now. One outstanding ping per session: while any wait has pinged, no other
 * wait pings; that wait gets exactly one repeat once it has been open `repeatMs`.
 */
export function sweep(waits: readonly NeedsYouWait[], now: number, cfg: { waitMs: number; repeatMs: number }): { ping?: string; repeat?: string } {
  const out = waits.find(w => w.pinged)
  if (out !== undefined) return !out.repeated && now - out.startedAt >= cfg.repeatMs ? { repeat: out.id } : {}
  const due = waits.filter(w => now - w.startedAt >= cfg.waitMs).sort((a, b) => a.startedAt - b.startedAt)[0]
  return due === undefined ? {} : { ping: due.id }
}

// ---------- log ----------

export function localStamp(ms: number): string {
  const d = new Date(ms)
  const off = -d.getTimezoneOffset()
  const pad = (n: number) => String(Math.floor(Math.abs(n))).padStart(2, '0')
  const sign = off >= 0 ? '+' : '-'
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}${sign}${pad(off / 60)}:${pad(off % 60)}`
}

/** One ping line. Never reply text, never a prompt-derived tag. */
export function pingLine(f: { at: number; id: string; session: string; project: string; kind: Kind; outcome: Outcome; seconds: number }): string {
  return [`${f.at}`, 'ping', `id=${f.id}`, `session=#${hash4(f.session)}`, `project=${stripMarkup(f.project)}`, `kind=${f.kind}`, `outcome=${f.outcome}`, `wait=${Math.round(f.seconds)}s`, localStamp(f.at)].join('\t')
}

export function ackLine(f: { at: number; id: string; session: string; delayMs: number }): string {
  return [`${f.at}`, 'ack', `id=${f.id}`, `session=#${hash4(f.session)}`, `delay=${Math.round(f.delayMs / 1000)}s`, localStamp(f.at)].join('\t')
}

function field(parts: readonly string[], name: string): string | undefined {
  const hit = parts.find(p => p.startsWith(`${name}=`))
  return hit === undefined ? undefined : hit.slice(name.length + 1)
}

/** Last 7 days: banners shown, and how many were acted on (an interaction within 3 min). */
export function summarize(lines: readonly string[], now: number): string {
  const since = now - 7 * 86_400_000
  const acks = new Map<string, number>()
  const pings: { id: string; outcome: string }[] = []
  for (const line of lines) {
    const parts = line.split('\t')
    const at = Number(parts[0])
    if (!(at >= since)) continue
    const id = field(parts, 'id')
    if (id === undefined) continue
    if (parts[1] === 'ack') acks.set(id, Number((field(parts, 'delay') ?? '').replace('s', '')) * 1000)
    else if (parts[1] === 'ping') pings.push({ id, outcome: field(parts, 'outcome') ?? '' })
  }
  const bannered = pings.filter(p => p.outcome === 'banner' || p.outcome === 'quiet')
  const acted = bannered.filter(p => (acks.get(p.id) ?? Infinity) <= ACK_WINDOW_MS)
  const pct = bannered.length === 0 ? 0 : Math.round((acted.length / bannered.length) * 100)
  return `Last 7 days: ${pings.length} pings, ${bannered.length} banners, ${acted.length} acted on within 3 min (${pct}%).`
}

// ---------- misc ----------

export function parseFront(stdout: string): string {
  return /="([^"]+)"/.exec(stdout)?.[1] ?? 'unknown'
}

export function isUnder(root: string, paths: string, home: string): boolean {
  return paths
    .split(',')
    .map(p => p.trim().replace(/^~(?=\/|$)/, home).replace(/\/+$/, ''))
    .some(p => p !== '' && (root === p || root.startsWith(`${p}/`)))
}

/** terminal-notifier reads a leading "-" as an option and a leading "[" as an escape; a hair space defuses both. */
export const plain = (text: string): string => (/^[-[]/.test(text) ? `\u200A${text}` : text)

