/** A dialog the user hasn't answered yet. */
export type NeedsYouWait = {
  id: string
  kind: 'permission' | 'plan' | 'question'
  /** Tool the permission dialog is for; '' for the other kinds. */
  tool: string
  /** Dialog type + header, never the full question text. */
  detail: string
  startedAt: number
  /** The one ping for this wait went out. */
  pinged: boolean
  /** The single repeat went out. */
  repeated: boolean
}

/** The banner awaiting the user's first interaction (for the `ack` log line). */
export type NeedsYouAck = { id: string; at: number }

/** Mirror of the global quiet mode in $.store, so the band can draw it. */
export type NeedsYouBand = { mode: 'on' | 'quiet' | 'off'; until: number | null; left: string }

declare module 'claude-code' {
  interface PluginState {
    'needs-you': {
      /** This turn was started by the user; consumed at turn.complete. */
      userTurn: boolean
      /** Dialog wait time accumulated during the running turn. */
      dialogMs: number
      waits: NeedsYouWait[]
      lastInteractionAt: number | null
      /** Last finished/error ping, for the per-session gap. */
      lastPingAt: number | null
      band: NeedsYouBand | null
      /** `/ping name` label. */
      label: string
      /** Cached git branch of the session. */
      branch: string | null
      ackPending: NeedsYouAck | null
    }
  }
}
